 if(view==='player'){const p=all.find(x=>x.id===id);if(!p){$('#main').innerHTML=prefix+menu+empty('找不到符合條件的球員');return;}$('#main').innerHTML=prefix+`<a class="rank-back" href="#composite/all">← 返回綜合榜</a><section class="radar-panel">${playerCard({...p,espnId:p.id})}<div class="radar-layout">${radarChart(p)}<div><h2>五維數據 / Five dimensions</h2><p>綜合 ${p.score.toFixed(1)} 分 · 出賽 ${p.stats.gamesPlayed} 場</p>${dimensions.map(([key,label],i)=>`<p><strong>${esc(label)}</strong>：${p.stats[key].toFixed(1)} · 同樣本百分位 ${p.radar[i].toFixed(0)}</p>`).join('')}</div></div><p class="fine-print">雷達為同一合格樣本中的相對百分位，並非球員能力值或預測。ESPN 本季 ${esc(source.season)}，${fmt(source.observedAt)} 取得。</p>${link(source.source,'數據來源')}</section>`;return;}
