 rows=rows.slice(0,30);$('#main').innerHTML=prefix+menu+`<h2 class="rank-section-title">${esc(names[view]??names.all)}</h2><div class="notice"><div><strong>${esc(source.season)} · 球季例行賽 / Regular Season</strong><small>${esc(info)} 數據 ${fmt(source.observedAt)}（台灣時間）；名單 ${esc(data.rosterDatabase?.availableTeams??0)}/30 隊可用。</small></div>${link(source.source,'ESPN 球季數據來源')}</div>${compositeAttribution(view,source)}`+(rows.length?`<div class="table-wrap"><table><thead><tr><th>排名 / Rank</th><th>球員 / Player</th><th>球隊 / Team</th><th>${view==='recent'?'近期場均加權分 / Form':view==='popular'?'七日瀏覽 / Views':'綜合分 / Score'}</th><th>場次 / Games</th><th>五維 / Radar</th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td>${i+1}</td><td>${playerCard({...p,espnId:p.id})}</td><td>${esc(teamText(p.team??''))}</td><td><strong>${view==='popular'?p.pop.views.toLocaleString():(p.form?.score??p.score).toFixed(1)}</strong></td><td>${view==='recent'?p.form.games:p.stats.gamesPlayed}</td><td><a href="#composite/player/${encodeURIComponent(p.id)}">查看五維 →</a>${p.pop?` · ${link(p.pop.article,'球員文章')} · ${link(p.pop.source,'瀏覽量原始資料')}<small>取得 ${fmt(p.pop.observedAt)}（台灣時間）</small>`:p.form?` · ${link(p.form.source,'球員比賽紀錄')}<small>取得 ${fmt(p.form.observedAt)}（台灣時間）</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty(view==='recent'?form?.reason??'近期紀錄不足或尚未取得': '目前沒有可核對的球員資料'));
